 html.Section([html.Div([html.Span('RESULTADOS SIN ATAJOS',className='eyebrow'),html.H2('¿Qué aportan los componentes de CICO?'),html.P('Comparación exploratoria sobre las mismas 2.049 imágenes de validación de 21 pacientes. Barras de error: desviación estándar entre cinco semillas, no intervalos de confianza.'),html.P('El modelo completo no supera consistentemente las variantes. No se demostró superioridad en estos contrastes.',className='result-takeaway'),html.A('Explorar semillas y curvas →',href='/ablaciones',className='button')]),dcc.Graph(figure=fig,config={'displayModeBar':False,'responsive':True})],className='results-feature'),
